// One original A-frame mesh extracted from the user's Chalkboard_sign_V1 GLB.
// Source: clon6767 on Sketchfab, CC BY 4.0. Coordinates quantized to 0.01 source units.
// Four instances in the upload were reduced to one; original triangle topology preserved.
export const TRANSLATION_SIGN_TEXT={
 title:'THE TRANSLATION AREA',
 subtitle:'Studies in transformation',
 lines:[
  'One image.',
  'Three interpretations.',
  '',
  'Source, translation',
  'and emergence.',
  '',
  'An experiment in',
  'marks becoming motion.'
 ],
 footer:'PROPORTION PIECE  ×  TOUCHDESIGNER'
};
const MESH='';
// Entrance-side placement is tied to the actual public glass doorway and
// actual gramophone cabinet, rather than the unrelated backroom entrance.
export const TRANSLATION_SIGN_SCALE=1.65; // 0.995m -> 1.64m tall, legible beside the gramophone.
export function translationAreaSignPlacement(entrance,gramophone,{scale=TRANSLATION_SIGN_SCALE}={}){
 if(!entrance || !gramophone || !['x','z'].includes(entrance.axis))return null;
 if(!Number.isFinite(entrance.at)||!Number.isFinite(entrance.centre)||
    !Number.isFinite(gramophone.x)||!Number.isFinite(gramophone.z))return null;
 const across=entrance.axis==='z'?'x':'z';
 const inward=entrance.axis==='z'?'z':'x';
 const door={x:entrance.axis==='z'?entrance.centre:entrance.at,
             z:entrance.axis==='x'?entrance.centre:entrance.at};
 const difference=gramophone[across]-door[across];
 const side=Math.sign(difference)||1;
 // Offset along the doorway wall so the enlarged 0.69m-wide A-frame and
 // a 0.3m margin sit entirely OUTSIDE the glass door's swing/clear opening.
 const doorWidth=Number.isFinite(entrance.width)?entrance.width:2.8;
 const half=doorWidth/2;
 const signRadius=.42*scale/2;
 const requiredLateralClearance=half+signRadius+.3;
 const between=Math.abs(difference)-.9;
 // Aim to be between the door and gramophone but keep door opening clear.
 // The door frame still occluded half the board: shift it along the wall,
 // to the gramophone side and clear of the glazing, not deeper through the door.
 const lateral=Math.max(requiredLateralClearance,
   Math.min(Math.max(requiredLateralClearance,between),Math.abs(difference)*.57)) + 1.3;
 const centre={
  ...door,
  [across]:door[across]+side*lateral,
  [inward]:door[inward]+Math.max(-.95,Math.min(.95,
   (gramophone[inward]-door[inward])*.42))
 };
 // Stay on the reception side of the glass; lateral separation clears its frame.
 const distanceToGramophone=Math.hypot(centre.x-gramophone.x,centre.z-gramophone.z);
 const distanceToDoor=Math.hypot(centre.x-door.x,centre.z-door.z);
 // If there is too little room, do not let a freestanding sign clip the
 // music cabinet: pull it 0.35m closer to the doorway's interior side.
 if(distanceToGramophone<1.1){
  const move=Math.sign(gramophone[inward]-door[inward])||1;
  centre[inward]-=move*.42;
 }
 const distanceToGramophoneFinal=Math.hypot(centre.x-gramophone.x,centre.z-gramophone.z);
 // Front of the board faces the reception interior and approaching visitors.
 const normal={x:0,z:0};
 normal[inward]=Math.sign(gramophone[inward]-door[inward])||1;
 return {
  x:centre.x,z:centre.z,yaw:Math.atan2(normal.x,normal.z),normal,
  zone:'reception-main-door-gramophone',axis:entrance.axis,doorAt:entrance.at,
  doorCentre:entrance.centre,doorWidth,side,scale,
  gramophone:{x:gramophone.x,z:gramophone.z},
  door:{x:door.x,z:door.z},
  distanceToDoor,distanceToGramophone:distanceToGramophoneFinal,
  lateralClearance:Math.abs(centre[across]-door[across])-(half+signRadius)
 };
}
function meshGeometry(THREE){
 const binary=atob(MESH),view=new DataView(Uint8Array.from(binary,c=>c.charCodeAt(0)).buffer);
 const vertices=view.getUint16(0,true),faces=view.getUint16(2,true);
 const positions=new Float32Array(vertices*3);
 for(let i=0;i<vertices*3;i++)positions[i]=view.getInt16(4+i*2,true)/10000;
 const indices=new Uint16Array(faces*3);
 for(let i=0;i<faces*3;i++)indices[i]=view.getUint16(4+vertices*6+i*2,true);
 const geo=new THREE.BufferGeometry();
 geo.setAttribute('position',new THREE.BufferAttribute(positions,3));
 geo.setIndex(new THREE.BufferAttribute(indices,1));
 geo.computeVertexNormals();
 return geo;
}
export function addPhiTranslationAreaSign(THREE,scene,{entrance,gramophone,elevation=0}){
 const place=translationAreaSignPlacement(entrance,gramophone);
 if(!place)return null;
 const root=new THREE.Group();
 root.name='phi-translation-area-doorway-sign';
 root.userData.kind='gallery-label';
 root.position.set(place.x,elevation+.016,place.z);
 root.rotation.y=place.yaw;
 root.scale.setScalar(place.scale);
 const mesh=new THREE.Mesh(meshGeometry(THREE),
  new THREE.MeshStandardMaterial({color:'#80614a',roughness:.94,side:THREE.DoubleSide}));
 // Original 0.42m × 0.995m × 0.34m A-frame, enlarged 65% to a ~1.64m entrance sign.
 root.add(mesh);
 const canvas=document.createElement('canvas');canvas.width=768;canvas.height=1450;
 const ctx=canvas.getContext('2d',{alpha:false});
 const cw=canvas.width,ch=canvas.height;
 ctx.fillStyle='#18373a';ctx.fillRect(0,0,cw,ch);
 ctx.strokeStyle='rgba(250,243,225,.3)';ctx.lineWidth=9;ctx.strokeRect(20,20,cw-40,ch-40);
 ctx.textAlign='center';
 ctx.fillStyle='#f0eadd';ctx.font='58px Georgia, serif';
 ctx.fillText('THE TRANSLATION',cw/2,175,cw-95);
 ctx.fillText('AREA',cw/2,255,cw-95);
 ctx.strokeStyle='#d7c6a7';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(90,310);ctx.lineTo(cw-90,310);ctx.stroke();
 ctx.fillStyle='#d9c9aa';ctx.font='italic 40px Georgia, serif';
 ctx.fillText('Studies in transformation',cw/2,390,cw-70);
 ctx.fillStyle='#f0eadc';ctx.font='45px Georgia, serif';
 const lines=['One image,','three interpretations.','','Source / translation /','emergence.','','An experiment in','marks becoming motion.'];
 lines.forEach((line,i)=>{if(line)ctx.fillText(line,cw/2,500+i*100,cw-100)});
 ctx.strokeStyle='#d7c6a7';ctx.beginPath();ctx.moveTo(100,1325);ctx.lineTo(cw-100,1325);ctx.stroke();
 ctx.font='26px Arial, sans-serif';ctx.fillText('PROPORTION PIECE  ×  TOUCHDESIGNER',cw/2,1390,cw-70);
 const texture=new THREE.CanvasTexture(canvas);
 texture.colorSpace=THREE.SRGBColorSpace;
 texture.anisotropy=4;
 const panel=new THREE.Mesh(new THREE.PlaneGeometry(.355,.734),
  new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide,toneMapped:false}));
 // Align with the original chalkboard face (the slope is present in the mesh).
 panel.position.set(0,.565,.087);
 panel.rotation.x=-Math.atan(11.16/79.38);
 panel.name='translation-area-curatorial-label';
 root.add(panel);
 scene.add(root);
 root.userData.placement=place;
 return {root,placement:place,meshFaces:152,dispose(){
  scene.remove(root);
  mesh.geometry.dispose();mesh.material.dispose();
  panel.geometry.dispose();panel.material.dispose();texture.dispose();
 }};
}
